-- Table without population growth
USE electricity;
DROP TABLE IF EXISTS peg;
CREATE TABLE IF NOT EXISTS peg(
   Year                                              INTEGER  NOT NULL PRIMARY KEY 
  ,Access_to_electricity_of_population               NUMERIC(11,8)
  ,Population_total                                  INTEGER  NOT NULL
  ,Urban_population_of_total_population              NUMERIC(11,8) NOT NULL
  ,Urban_population_growth_annual_                   NUMERIC(11,9) NOT NULL
  ,Rural_population_growth_annual_                   NUMERIC(11,9) NOT NULL
  ,Rural_population_of_total_population              NUMERIC(11,8) NOT NULL
  ,Rural_population                                  INTEGER  NOT NULL
  ,Access_to_electricity_rural_of_rural_population   NUMERIC(11,9)
  ,Access_to_electricity_rural_of_rural_population_1 NUMERIC(11,9)
  ,Access_to_electricity_urban_of_urban_population   NUMERIC(11,8)
  ,GDPGDP_growth_annual_                             NUMERIC(12,9) NOT NULL
  ,GDPGDP_per_capita_growth_annual_                  NUMERIC(12,9) NOT NULL
);

SELECT *
FROM electricity.peg;